// Unit tests for scripts/security-alert-issues/manifests.mjs.
//   node --test scripts/security-alert-issues/manifests.test.mjs
import assert from "node:assert/strict";
import { test } from "node:test";

import {
	assessFinding,
	isLockfile,
	normalizePackageName,
	pinnedVersionFor,
	pinnedVersionFromPackageJson,
	pinnedVersionFromRequirements,
	pinnedVersionReason,
	readPinnedVersion,
	requirementFor,
} from "./manifests.mjs";

const REQUIREMENTS = `#
# autogenerated by pip-compile
#
virtualenv==21.14.7 \\
    --hash=sha256:abc \\
    --hash=sha256:def
flask[async]>=2.0
pre-commit
`;

test("package names normalise the way pip compares them", () => {
	assert.equal(normalizePackageName("Flask_Login"), "flask-login");
	assert.equal(normalizePackageName("Flask.Login"), "flask-login");
	assert.equal(normalizePackageName("flask--login"), "flask-login");
	assert.equal(normalizePackageName("  Zope.Interface  "), "zope-interface");
	assert.equal(normalizePackageName(""), "");
	assert.equal(normalizePackageName(null), "");
});

test("a requirement line carries the spec and whether it is an exact pin", () => {
	assert.deepEqual(requirementFor(REQUIREMENTS, "virtualenv"), {
		spec: "==21.14.7",
		exact: true,
	});
	assert.deepEqual(requirementFor(REQUIREMENTS, "flask"), { spec: ">=2.0", exact: false });
	// A bare name is a requirement with no spec at all.
	assert.deepEqual(requirementFor(REQUIREMENTS, "pre-commit"), { spec: "", exact: false });
	assert.equal(requirementFor(REQUIREMENTS, "missing"), null);
	assert.equal(requirementFor("", "flask"), null);
	assert.equal(requirementFor(REQUIREMENTS, ""), null);
	// Comments and blank lines are skipped; the name is compared normalised.
	assert.deepEqual(requirementFor("# flask==9.9\nFlask==2.0", "flask"), {
		spec: "==2.0",
		exact: true,
	});
	// Include lines and direct references do not look like requirements.
	assert.equal(requirementFor("-r other.txt", "flask"), null);
	assert.equal(requirementFor("flask @ git+https://example.test/repo.git", "flask"), null);
});

test("an extras pin still counts as an exact pin", () => {
	const requirement = requirementFor("requests[socks]==2.31.0", "requests");
	assert.deepEqual(requirement, { spec: "==2.31.0", exact: true });
	assert.equal(pinnedVersionFromRequirements("requests[socks]==2.31.0", "requests"), "2.31.0");
});

test("the pinned version drops the == operator", () => {
	assert.equal(pinnedVersionFromRequirements("flask == 2.0.1", "flask"), "2.0.1");
	assert.equal(pinnedVersionFromRequirements("flask>=2.0", "flask"), null);
	assert.equal(pinnedVersionFromRequirements("flask", "flask"), null);
});

test("a package.json dependency is a pin only when exact", () => {
	assert.deepEqual(
		pinnedVersionFromPackageJson(JSON.stringify({ dependencies: { vite: "8.3.3" } }), "vite"),
		{ version: "8.3.3", range: null, kind: "pinned" },
	);
	assert.deepEqual(
		pinnedVersionFromPackageJson(JSON.stringify({ dependencies: { vite: "^8.3.3" } }), "vite"),
		{ version: null, range: "^8.3.3", kind: "range" },
	);
	// A prerelease pin still counts as exact.
	assert.deepEqual(
		pinnedVersionFromPackageJson(
			JSON.stringify({ dependencies: { vite: "8.3.3-beta.1" } }),
			"vite",
		),
		{ version: "8.3.3-beta.1", range: null, kind: "pinned" },
	);
});

test("every dependency group of package.json is read, dependencies first", () => {
	for (const group of [
		"dependencies",
		"devDependencies",
		"optionalDependencies",
		"peerDependencies",
	]) {
		const parsed = pinnedVersionFromPackageJson(
			JSON.stringify({ [group]: { vite: "1.0.0" } }),
			"vite",
		);
		assert.equal(parsed.version, "1.0.0", `group: ${group}`);
	}
	const parsed = pinnedVersionFromPackageJson(
		JSON.stringify({ dependencies: { vite: "1.0.0" }, devDependencies: { vite: "2.0.0" } }),
		"vite",
	);
	assert.equal(parsed.version, "1.0.0");
});

test("a package.json that is not JSON, or misses the package, reads nothing", () => {
	assert.equal(pinnedVersionFromPackageJson("not json", "vite"), null);
	assert.equal(pinnedVersionFromPackageJson(JSON.stringify({ dependencies: {} }), "vite"), null);
	assert.equal(
		pinnedVersionFromPackageJson(JSON.stringify({ dependencies: { vite: "" } }), "vite"),
		null,
	);
	// The name matches exactly; a scoped package is a different package.
	assert.equal(
		pinnedVersionFromPackageJson(
			JSON.stringify({ dependencies: { "@scope/vite": "1.0.0" } }),
			"vite",
		),
		null,
	);
});

test("the lockfile names are recognised wherever they sit", () => {
	for (const path of [
		"bun.lock",
		"bun.lockb",
		"pnpm-lock.yaml",
		"package-lock.json",
		"yarn.lock",
		"poetry.lock",
		"cli/pnpm-lock.yaml",
		"a/b/package-lock.json",
	]) {
		assert.equal(isLockfile(path), true, `path: ${path}`);
	}
	for (const path of ["package.json", "requirements.txt", "bun.lock.txt", "my-yarn.lock"]) {
		assert.equal(isLockfile(path), false, `path: ${path}`);
	}
	assert.equal(isLockfile(null), false);
});

test("the manifest kind decides what pinned version means", () => {
	assert.deepEqual(pinnedVersionFor(null, "vite", "package.json"), {
		version: null,
		range: null,
		kind: "unknown",
	});
	// A lockfile is read but pins no single version.
	assert.deepEqual(pinnedVersionFor("lockfileVersion: 1\n", "vite", "pnpm-lock.yaml"), {
		version: null,
		range: null,
		kind: "unknown",
	});
	// A requirements .in file is read the same as .txt.
	assert.deepEqual(
		pinnedVersionFor("flask==2.0.1\n", "flask", "requirements.in"),
		{ version: "2.0.1", range: null, kind: "pinned" },
	);
	// An unknown manifest type reads nothing even when the text names the package.
	assert.deepEqual(pinnedVersionFor("vite 8.3.3\n", "vite", "notes.md"), {
		version: null,
		range: null,
		kind: "unknown",
	});
	// The name test is endsWith, so `my-package.json` also reads as package.json.
	// Current behaviour, pinned.
	assert.deepEqual(
		pinnedVersionFor(JSON.stringify({ dependencies: { vite: "1.0.0" } }), "vite", "my-package.json"),
		{ version: "1.0.0", range: null, kind: "pinned" },
	);
});

test("the reason names the manifest shape that hid the version", () => {
	assert.equal(
		pinnedVersionReason({ version: null, range: "^1.0.0", kind: "range" }, "package.json"),
		"the manifest pins a range (`^1.0.0`), not one version",
	);
	assert.equal(
		pinnedVersionReason({ kind: "unknown" }, "bun.lock"),
		"the manifest is a lockfile, so it pins a resolved tree rather than one version",
	);
	assert.equal(
		pinnedVersionReason({ kind: "unknown" }, "README.md"),
		"the manifest carries no version for this package",
	);
});

test("the installed version answers when the manifest pins none", () => {
	const finding = { manifestPath: "bun.lock", packageName: "vite", installedVersion: "8.3.1" };
	assert.deepEqual(readPinnedVersion(finding, () => "lockfileVersion: 1\n"), {
		version: "8.3.1",
		range: null,
		kind: "pinned",
	});
	// Without a manifest path the reader is never called.
	const noPath = { packageName: "vite", installedVersion: "8.3.1" };
	assert.deepEqual(
		readPinnedVersion(noPath, () => {
			throw new Error("must not be called");
		}),
		{ version: "8.3.1", range: null, kind: "pinned" },
	);
	// No pin anywhere and nothing resolved: the manifest answer stands.
	const nothing = { manifestPath: "bun.lock", packageName: "vite" };
	assert.deepEqual(readPinnedVersion(nothing, () => "x"), {
		version: null,
		range: null,
		kind: "unknown",
	});
	// A manifest that pins a range still leaves the resolved version as the answer.
	const ranged = {
		manifestPath: "package.json",
		packageName: "vite",
		installedVersion: "8.3.1",
	};
	assert.deepEqual(
		readPinnedVersion(ranged, () => JSON.stringify({ dependencies: { vite: "^8.0.0" } })),
		{ version: "8.3.1", range: null, kind: "pinned" },
	);
});

test("a manifest pin beats the resolved version the scanner reported", () => {
	const finding = { manifestPath: "requirements.txt", packageName: "flask", installedVersion: "9.9" };
	assert.deepEqual(readPinnedVersion(finding, () => "flask==2.0.1\n"), {
		version: "2.0.1",
		range: null,
		kind: "pinned",
	});
});

test("the finding gains its pinned version and the verdict it implies", () => {
	const finding = {
		manifestPath: "requirements.txt",
		packageName: "flask",
		patchedVersion: "2.0.2",
		vulnerableRange: "< 2.0.2",
	};
	const assessed = assessFinding(finding, () => "flask==2.0.1\n");
	assert.deepEqual(assessed.pinned, { version: "2.0.1", range: null, kind: "pinned" });
	assert.equal(assessed.assessment.status, "affected");
	// The finding itself is untouched otherwise.
	assert.equal(assessed.manifestPath, "requirements.txt");
});
